[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.1.0/fonts/remixicon.css" rel="stylesheet">
<style>
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{
  --bg:#0A0A0A;--bg-elevated:#141414;--bg-card:#1A1A1A;--bg-card-hover:#222;
  --white:#FFFFFF;--gray-100:#F5F5F5;--gray-200:#E5E5E5;--gray-300:#D4D4D4;
  --gray-400:#A3A3A3;--gray-500:#737373;--gray-600:#525252;--gray-700:#404040;--gray-800:#262626;--gray-900:#171717;
  --accent:#3B82F6;--accent-hover:#60A5FA;--accent-warm:#F59E0B;
  --font:'Inter',system-ui,-apple-system,sans-serif;
  --nav-h:72px;--section-pad:clamp(80px,10vw,140px);
  --max-w:1280px;--ease:cubic-bezier(.4,0,.2,1);
}
html{scroll-behavior:smooth;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
body{font-family:var(--font);background:var(--bg);color:var(--white);line-height:1.6;overflow-x:hidden}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none;color:inherit}
img{display:block;max-width:100%}
.container{max-width:var(--max-w);margin:0 auto;padding:0 clamp(20px,4vw,48px)}

/* NAV */
.nav{position:fixed;top:0;left:0;right:0;height:var(--nav-h);z-index:100;background:rgba(10,10,10,.85);backdrop-filter:blur(20px);border-bottom:1px solid rgba(255,255,255,.06);transition:background .3s var(--ease)}
.nav-inner{display:flex;align-items:center;justify-content:space-between;height:100%;max-width:var(--max-w);margin:0 auto;padding:0 clamp(20px,4vw,48px)}
.nav-logo{font-size:1.25rem;font-weight:800;letter-spacing:-.02em}
.nav-logo span{color:var(--accent)}
.nav-links{display:flex;align-items:center;gap:32px}
.nav-links a{font-size:.875rem;font-weight:500;color:var(--gray-400);transition:color .2s}
.nav-links a:hover{color:var(--white)}
.nav-right{display:flex;align-items:center;gap:20px}
.lang-selector{position:relative}
.lang-btn{display:flex;align-items:center;gap:6px;font-size:.8125rem;font-weight:500;color:var(--gray-400);padding:6px 12px;border-radius:6px;transition:all .2s}
.lang-btn:hover,.lang-btn.active{color:var(--white);background:var(--bg-card)}
.lang-dropdown{position:absolute;top:calc(100% + 8px);right:0;background:var(--bg-card);border:1px solid var(--gray-800);border-radius:10px;padding:6px;min-width:180px;opacity:0;visibility:hidden;transform:translateY(-4px);transition:all .2s var(--ease);z-index:10}
.lang-dropdown.open{opacity:1;visibility:visible;transform:translateY(0)}
.lang-dropdown button{display:flex;align-items:center;gap:10px;width:100%;padding:10px 14px;font-size:.8125rem;font-weight:500;border-radius:6px;color:var(--gray-400);transition:all .15s}
.lang-dropdown button:hover,.lang-dropdown button.selected{color:var(--white);background:var(--gray-800)}
.hamburger{display:none;flex-direction:column;gap:5px;padding:8px}
.hamburger span{display:block;width:22px;height:2px;background:var(--white);border-radius:2px;transition:all .3s var(--ease)}
.mobile-menu{display:none;position:fixed;top:var(--nav-h);left:0;right:0;bottom:0;background:var(--bg);z-index:99;padding:32px clamp(20px,4vw,48px);flex-direction:column;gap:8px}
.mobile-menu.open{display:flex}
.mobile-menu a{font-size:1.5rem;font-weight:600;color:var(--gray-300);padding:16px 0;border-bottom:1px solid var(--gray-800);transition:color .2s}
.mobile-menu a:hover{color:var(--white)}

/* HERO */
.hero{position:relative;min-height:100vh;padding-top:var(--nav-h);display:flex;align-items:center;overflow:hidden}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg-slide{position:absolute;inset:0;opacity:0;transition:opacity .8s var(--ease)}
.hero-bg-slide.active{opacity:1}
.hero-bg-slide .bg-gradient{position:absolute;inset:0}
.hero-content{position:relative;z-index:2;width:100%;padding:80px 0}
.hero-inner{max-width:var(--max-w);margin:0 auto;padding:0 clamp(20px,4vw,48px);display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.hero-text{max-width:600px}
.hero-tag{display:inline-flex;align-items:center;gap:8px;font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.1em;color:var(--accent);margin-bottom:24px;padding:8px 16px;background:rgba(59,130,246,.1);border:1px solid rgba(59,130,246,.2);border-radius:100px}
.hero-title{font-size:clamp(2.5rem,5.5vw,4.5rem);font-weight:800;line-height:1.05;letter-spacing:-.03em;margin-bottom:24px}
.hero-desc{font-size:clamp(1rem,1.5vw,1.25rem);color:var(--gray-400);line-height:1.7;margin-bottom:40px;max-width:520px}
.hero-cta{display:inline-flex;align-items:center;gap:10px;padding:16px 32px;background:var(--accent);color:var(--white);font-size:.9375rem;font-weight:600;border-radius:10px;transition:all .25s var(--ease)}
.hero-cta:hover{background:var(--accent-hover);transform:translateY(-2px);box-shadow:0 8px 30px rgba(59,130,246,.3)}
.hero-card{position:relative;background:var(--bg-card);border:1px solid var(--gray-800);border-radius:16px;overflow:hidden;aspect-ratio:4/3}
.hero-card-img{width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .8s var(--ease)}
.hero-card-img.active{opacity:1}
.hero-card-overlay{position:absolute;bottom:0;left:0;right:0;padding:24px;background:linear-gradient(transparent,rgba(0,0,0,.8))}
.hero-card-overlay p{font-size:.8125rem;color:var(--gray-300);line-height:1.5}

.hero-controls{display:flex;align-items:center;gap:16px;margin-top:48px}
.hero-dots{display:flex;gap:8px}
.hero-dot{width:8px;height:8px;border-radius:50%;background:var(--gray-700);transition:all .3s var(--ease);cursor:pointer}
.hero-dot.active{background:var(--accent);width:32px;border-radius:4px}
.hero-nav-btn{width:40px;height:40px;border-radius:50%;border:1px solid var(--gray-700);display:flex;align-items:center;justify-content:center;color:var(--gray-400);transition:all .2s;font-size:1.125rem}
.hero-nav-btn:hover{border-color:var(--white);color:var(--white)}

/* TEAM */
.team-section{padding:var(--section-pad) 0;background:var(--bg)}
.section-header{margin-bottom:60px}
.section-tag{font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.12em;color:var(--accent);margin-bottom:16px}
.section-title{font-size:clamp(2rem,4vw,3.25rem);font-weight:800;letter-spacing:-.025em;line-height:1.1;margin-bottom:16px}
.section-subtitle{font-size:clamp(1rem,1.3vw,1.125rem);color:var(--gray-400);max-width:600px;line-height:1.7}

.region-tabs{display:flex;gap:4px;margin-bottom:48px;background:var(--bg-elevated);padding:4px;border-radius:12px;width:fit-content;flex-wrap:wrap}
.region-tab{padding:12px 24px;font-size:.875rem;font-weight:600;border-radius:8px;color:var(--gray-500);transition:all .25s var(--ease);white-space:nowrap}
.region-tab:hover{color:var(--gray-300)}
.region-tab.active{background:var(--accent);color:var(--white)}

.team-carousel-wrapper{position:relative;overflow:hidden}
.team-carousel{display:flex;gap:24px;transition:transform .5s var(--ease)}
.team-card{min-width:340px;max-width:340px;background:var(--bg-card);border:1px solid var(--gray-800);border-radius:16px;overflow:hidden;flex-shrink:0;transition:all .3s var(--ease)}
.team-card:hover{border-color:var(--gray-700);transform:translateY(-4px)}
.team-card-img{width:100%;aspect-ratio:4/3;background:var(--bg-elevated);position:relative;overflow:hidden}
.team-card-img .placeholder{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:3rem;color:var(--gray-700)}
.team-card-img .img-overlay{position:absolute;inset:0;background:linear-gradient(135deg,rgba(59,130,246,.15),rgba(139,92,246,.15))}
.team-card-body{padding:28px}
.team-card-quote{font-size:.9375rem;color:var(--gray-300);line-height:1.7;margin-bottom:20px;font-style:italic;position:relative;padding-left:20px;border-left:2px solid var(--accent)}
.team-card-name{font-size:1.0625rem;font-weight:700;margin-bottom:4px}
.team-card-role{font-size:.8125rem;color:var(--gray-500);margin-bottom:4px}
.team-card-office{font-size:.8125rem;color:var(--gray-500);display:flex;align-items:center;gap:4px;margin-bottom:20px}
.team-card-cta{display:inline-flex;align-items:center;gap:6px;font-size:.8125rem;font-weight:600;color:var(--accent);transition:color .2s}
.team-card-cta:hover{color:var(--accent-hover)}

.carousel-nav{display:flex;align-items:center;gap:12px;margin-top:32px;justify-content:flex-end}
.carousel-btn{width:48px;height:48px;border-radius:50%;border:1px solid var(--gray-700);display:flex;align-items:center;justify-content:center;color:var(--gray-400);font-size:1.25rem;transition:all .2s}
.carousel-btn:hover{border-color:var(--white);color:var(--white);background:var(--bg-card)}
.carousel-btn:disabled{opacity:.3;cursor:not-allowed}

/* WORK */
.work-section{padding:var(--section-pad) 0;background:var(--bg-elevated);border-top:1px solid var(--gray-800);border-bottom:1px solid var(--gray-800)}
.work-carousel-wrapper{position:relative;overflow:hidden;margin:0 calc(-1 * clamp(20px,4vw,48px))}
.work-carousel{display:flex;gap:24px;padding:0 clamp(20px,4vw,48px);overflow-x:auto;scroll-behavior:smooth;scrollbar-width:none;-ms-overflow-style:none;cursor:grab;scroll-snap-type:x mandatory}
.work-carousel::-webkit-scrollbar{display:none}
.work-carousel.grabbing{cursor:grabbing;scroll-behavior:auto}
.work-card{min-width:380px;max-width:380px;flex-shrink:0;scroll-snap-align:start;background:var(--bg-card);border:1px solid var(--gray-800);border-radius:16px;overflow:hidden;transition:all .3s var(--ease)}
.work-card:hover{border-color:var(--gray-600);transform:translateY(-4px)}
.work-card-img{width:100%;aspect-ratio:16/10;position:relative;overflow:hidden}
.work-card-img .placeholder-work{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:1.5rem;font-weight:700;color:var(--gray-600);padding:20px;text-align:center}
.work-card-body{padding:24px}
.work-card-client{font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:8px}
.work-card-title{font-size:1.125rem;font-weight:700;line-height:1.35;margin-bottom:12px}
.work-card-quote{font-size:.8125rem;color:var(--gray-400);line-height:1.6;margin-bottom:8px;font-style:italic}
.work-card-attr{font-size:.75rem;color:var(--gray-500);font-weight:500}
.work-scroll-hint{display:flex;align-items:center;gap:8px;margin-top:24px;font-size:.8125rem;color:var(--gray-500)}
.work-scroll-hint i{animation:scrollHint 2s infinite}
@keyframes scrollHint{0%,100%{transform:translateX(0)}50%{transform:translateX(6px)}}

/* CTA BANNER */
.cta-banner{padding:var(--section-pad) 0;text-align:center;position:relative;overflow:hidden}
.cta-banner::before{content:'';position:absolute;top:50%;left:50%;width:600px;height:600px;background:radial-gradient(circle,rgba(59,130,246,.08),transparent 70%);transform:translate(-50%,-50%);pointer-events:none}
.cta-banner-title{font-size:clamp(2.5rem,5vw,4rem);font-weight:800;letter-spacing:-.03em;margin-bottom:24px}
.cta-banner-body{font-size:clamp(1rem,1.3vw,1.125rem);color:var(--gray-400);max-width:680px;margin:0 auto 40px;line-height:1.7}
.cta-banner .hero-cta{padding:18px 40px;font-size:1rem}

/* HOW WE WORK */
.how-section{padding:var(--section-pad) 0;background:var(--bg-elevated);border-top:1px solid var(--gray-800);border-bottom:1px solid var(--gray-800)}
.how-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.how-visual{position:relative;aspect-ratio:1;background:var(--bg-card);border-radius:24px;overflow:hidden;border:1px solid var(--gray-800)}
.how-visual-inner{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,rgba(59,130,246,.08),rgba(245,158,11,.08))}
.how-visual-inner i{font-size:6rem;color:var(--gray-700)}
.how-text .section-title{margin-bottom:24px}
.how-text p{font-size:clamp(1rem,1.2vw,1.0625rem);color:var(--gray-400);line-height:1.8;margin-bottom:32px}
.how-text .hero-cta{padding:14px 28px;font-size:.875rem}

/* INSIGHTS */
.insights-section{padding:var(--section-pad) 0}
.insights-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:24px}
.insight-card{background:var(--bg-card);border:1px solid var(--gray-800);border-radius:14px;overflow:hidden;transition:all .3s var(--ease)}
.insight-card:hover{border-color:var(--gray-600);transform:translateY(-4px)}
.insight-card-img{width:100%;aspect-ratio:16/9;position:relative;overflow:hidden}
.insight-card-img .placeholder-insight{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:2rem;color:var(--gray-700)}
.insight-card-body{padding:20px}
.insight-card-type{display:inline-flex;align-items:center;gap:6px;font-size:.6875rem;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:10px;padding:4px 10px;background:rgba(59,130,246,.08);border-radius:4px}
.insight-card-title{font-size:1rem;font-weight:700;line-height:1.35;margin-bottom:14px}
.insight-card-cta{display:inline-flex;align-items:center;gap:6px;font-size:.8125rem;font-weight:600;color:var(--accent);transition:all .2s}
.insight-card-cta:hover{color:var(--accent-hover);gap:10px}

/* PRINCIPLES */
.principles-section{padding:var(--section-pad) 0;background:var(--bg-elevated);border-top:1px solid var(--gray-800)}
.principles-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:32px;counter-reset:principle}
.principle-card{counter-increment:principle;padding:36px;background:var(--bg-card);border:1px solid var(--gray-800);border-radius:16px;transition:all .3s var(--ease)}
.principle-card:hover{border-color:var(--accent);transform:translateY(-4px)}
.principle-card::before{content:counter(principle,decimal-leading-zero);font-size:3rem;font-weight:800;color:var(--gray-800);line-height:1;margin-bottom:20px;display:block;transition:color .3s}
.principle-card:hover::before{color:var(--accent)}
.principle-card h3{font-size:1.25rem;font-weight:700;margin-bottom:14px;line-height:1.3}
.principle-card p{font-size:.9375rem;color:var(--gray-400);line-height:1.7}

/* FOOTER */
.footer{padding:80px 0 40px;background:var(--bg);border-top:1px solid var(--gray-800)}
.footer-top{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-bottom:64px}
.footer-cta-block h3{font-size:1.5rem;font-weight:700;margin-bottom:12px}
.footer-cta-block p{font-size:.9375rem;color:var(--gray-400);margin-bottom:24px;line-height:1.7;max-width:400px}
.footer-cta-link{display:inline-flex;align-items:center;gap:8px;font-size:.9375rem;font-weight:600;color:var(--accent);transition:all .2s}
.footer-cta-link:hover{color:var(--accent-hover);gap:12px}
.footer-links{display:flex;gap:32px;margin-bottom:48px;flex-wrap:wrap}
.footer-links a{font-size:.875rem;color:var(--gray-500);transition:color .2s}
.footer-links a:hover{color:var(--white)}
.footer-bottom{display:flex;align-items:center;justify-content:space-between;padding-top:32px;border-top:1px solid var(--gray-800);flex-wrap:wrap;gap:16px}
.footer-legal{font-size:.75rem;color:var(--gray-600)}
.footer-legal-links{display:flex;gap:20px;flex-wrap:wrap}
.footer-legal-links a{font-size:.75rem;color:var(--gray-600);transition:color .2s}
.footer-legal-links a:hover{color:var(--gray-400)}

/* COOKIE */
.cookie-banner{position:fixed;bottom:0;left:0;right:0;background:var(--bg-card);border-top:1px solid var(--gray-800);padding:20px;z-index:200;transform:translateY(100%);transition:transform .4s var(--ease)}
.cookie-banner.visible{transform:translateY(0)}
.cookie-inner{max-width:var(--max-w);margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.cookie-text{font-size:.8125rem;color:var(--gray-400);max-width:600px;line-height:1.6}
.cookie-text a{color:var(--accent);text-decoration:underline}
.cookie-actions{display:flex;gap:12px;flex-shrink:0;flex-wrap:wrap}
.cookie-btn{padding:10px 20px;font-size:.8125rem;font-weight:600;border-radius:8px;transition:all .2s}
.cookie-btn-accept{background:var(--accent);color:var(--white)}
.cookie-btn-accept:hover{background:var(--accent-hover)}
.cookie-btn-manage{border:1px solid var(--gray-700);color:var(--gray-300)}
.cookie-btn-manage:hover{border-color:var(--gray-500);background:var(--gray-800)}
.cookie-btn-decline{color:var(--gray-500)}
.cookie-btn-decline:hover{color:var(--gray-300)}

/* RESPONSIVE */
@media(max-width:1024px){
  .hero-inner{grid-template-columns:1fr;gap:40px}
  .hero-card{max-width:560px}
  .how-grid{grid-template-columns:1fr;gap:40px}
  .how-visual{max-width:480px}
  .footer-top{grid-template-columns:1fr;gap:40px}
}
@media(max-width:768px){
  .nav-links{display:none}
  .hamburger{display:flex}
  .hero{min-height:auto;padding-top:calc(var(--nav-h) + 40px);padding-bottom:60px}
  .hero-content{padding:40px 0}
  .team-card{min-width:290px;max-width:290px}
  .work-card{min-width:300px;max-width:300px}
  .region-tabs{width:100%}
  .region-tab{padding:10px 18px;font-size:.8125rem}
  .section-header{margin-bottom:40px}
  .footer-bottom{flex-direction:column;align-items:flex-start}
  .cookie-inner{flex-direction:column;align-items:flex-start}
}
@media(max-width:480px){
  .hero-title{font-size:2rem}
  .team-card{min-width:260px;max-width:260px}
  .work-card{min-width:260px;max-width:260px}
}
</style>
</head>
<body>

<!-- NAVIGATION -->
<nav class="nav" id="nav">
  <div class="nav-inner">
    <a href="#" class="nav-logo">Leap<span>Studio</span></a>
    <div class="nav-links">
      <a href="#insights-section">Insights</a>
      <a href="#work-section">Work</a>
      <a href="#how-section">Services</a>
      <a href="#team-section">Culture</a>
      <a href="#footer">Make Your Mark</a>
      <a href="#cta-banner">Contact Us</a>
    </div>
    <div class="nav-right">
      <div class="lang-selector">
        <button class="lang-btn" id="langBtn" aria-expanded="false" aria-haspopup="true">
          <i class="ri-global-line"></i> Global EN <i class="ri-arrow-down-s-line"></i>
        </button>
        <div class="lang-dropdown" id="langDropdown" role="menu">
          <button role="menuitem" class="selected" data-lang="en">
            <i class="ri-global-line"></i> Global EN
          </button>
          <button role="menuitem" data-lang="fr">
            <i class="ri-flag-line"></i> France FR
          </button>
          <button role="menuitem" data-lang="cn">
            <i class="ri-flag-line"></i> China CN
          </button>
        </div>
      </div>
      <button class="hamburger" id="hamburger" aria-label="Open menu">
        <span></span><span></span><span></span>
      </button>
    </div>
  </div>
</nav>

<!-- MOBILE MENU -->
<div class="mobile-menu" id="mobileMenu">
  <a href="#insights-section" onclick="closeMobile()">Insights</a>
  <a href="#work-section" onclick="closeMobile()">Work</a>
  <a href="#how-section" onclick="closeMobile()">Services</a>
  <a href="#team-section" onclick="closeMobile()">Culture</a>
  <a href="#footer" onclick="closeMobile()">Make Your Mark</a>
  <a href="#cta-banner" onclick="closeMobile()">Contact Us</a>
</div>

<!-- HERO -->
<section class="hero" id="hero">
  <div class="hero-bg" id="heroBg"></div>
  <div class="hero-content">
    <div class="hero-inner">
      <div class="hero-text">
        <div class="hero-tag"><i class="ri-sparkling-2-fill"></i> <span id="heroTag">Featured</span></div>
        <h1 class="hero-title" id="heroTitle">Futurescape: Synthetic Realities</h1>
        <p class="hero-desc" id="heroDesc">Welcome to the Futurescape. Discover trends and insights on the future of human-AI chemistry.</p>
        <a href="#" class="hero-cta" id="heroCta">Read the report <i class="ri-arrow-right-line"></i></a>
        <div class="hero-controls">
          <div class="hero-dots" id="heroDots"></div>
          <button class="hero-nav-btn" id="heroPrev" aria-label="Previous slide"><i class="ri-arrow-left-s-line"></i></button>
          <button class="hero-nav-btn" id="heroNext" aria-label="Next slide"><i class="ri-arrow-right-s-line"></i></button>
